(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-976":{scenario:{company:"Lam Giang Provincial Digital Center",supervisor:{name:"Khúc Duy Phong",role:{vi:"Trưởng phòng Chính phủ số",en:"Head of Digital Government"}},ref_code:"DVC-0315",title:{vi:"Đánh giá thật. Lợi ích thật. Dữ liệu an toàn.",en:"Honest rating. Real benefit. Safe data."},brief:{vi:"Đây là tình huống đào tạo. Bạn lập đề án nâng cấp dịch vụ công DVC-0315 (cấp phép tổ chức sự kiện, mô phỏng). Quy định chuyên ngành buộc người nộp đến trực tiếp ký nhận kết quả và xuất trình bản gốc tại quầy. Dữ liệu: 48000 hồ sơ/năm, tỷ lệ nộp trực tuyến mục tiêu 65%; chi phí xã hội mỗi hồ sơ: trực tiếp 185000 đ, trực tuyến toàn trình 60000 đ, trực tuyến một phần 95000 đ. Sửa mức độ dịch vụ và lợi ích hằng năm (triệu đồng) trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"This is a training scenario. You are drafting the upgrade proposal for public service DVC-0315 (event permit, simulated). Sector rules require applicants to come in person to sign for the result and show originals at the counter. Data: 48000 files/year, target online share 65%; social cost per file: in person 185000 VND, full online 60000 VND, partial online 95000 VND. Correct the service level and the annual benefit (million VND) in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Phiếu đánh giá mức độ DVC & phân tích lợi ích · DVC-0315",en:"Service level assessment & benefit analysis · DVC-0315"},fields:[{id:"DVC_LEVEL",label:{vi:"Mức độ dịch vụ công trực tuyến",en:"Online public service level"},initial:"FULL-ONLINE",expected:"PARTIAL-ONLINE",choices:["FULL-ONLINE","PARTIAL-ONLINE","IN-PERSON"],reference:"Phiếu đánh giá mức độ DVC",hint:{vi:"Chỉ cần một bước bắt buộc người dân đến trực tiếp là dịch vụ chưa đạt mức toàn trình.",en:"A single mandatory in-person step means the service is not yet fully online."}},{id:"BENEFIT_M",label:{vi:"Lợi ích xã hội hằng năm (triệu đồng)",en:"Annual social benefit (million VND)"},initial:"6000",expected:"2808",reference:"Bảng phân tích chi phí - lợi ích",ref_value:{vi:"48000 hồ sơ/năm; trực tuyến 65%; chi phí: trực tiếp 185000, toàn trình 60000, một phần 95000 đ",en:"48000 files/yr; 65% online; cost: in person 185000, full 60000, partial 95000 VND"},hint:{vi:"Lợi ích chỉ phát sinh trên phần hồ sơ chuyển sang trực tuyến và theo chi phí của đúng mức độ dịch vụ.",en:"Benefits arise only on files that move online and at the cost of the correct service level."}}],sop32:{vi:"Lợi ích hằng năm = số hồ sơ/năm x tỷ lệ nộp trực tuyến x (chi phí hồ sơ trực tiếp - chi phí hồ sơ trực tuyến của đúng mức độ dịch vụ); quy đổi ra triệu đồng.",en:"Annual benefit = files per year x online share x (in-person cost per file - online cost per file at the correct service level); convert to million VND."},context:{label:"EA / DVC-0315",metrics:[{label:{vi:"Hồ sơ mỗi năm",en:"Files per year"},value:"48,000"},{label:{vi:"Tỷ lệ trực tuyến mục tiêu",en:"Target online share"},value:"65%"},{label:{vi:"Chi phí trực tiếp / hồ sơ",en:"In-person cost / file"},value:"185,000 VND"},{label:{vi:"Chi phí một phần / hồ sơ",en:"Partial online cost / file"},value:"95,000 VND"}]},crisis:{vi:"Nhà thầu đề nghị xuất 50000 bản ghi công dân thật từ cơ sở dữ liệu của tỉnh để “huấn luyện chatbot” kịp buổi trình diễn với lãnh đạo tỉnh tuần sau; trưởng phòng đã đồng ý miệng và dặn đừng làm thủ tục cho mất thời gian.",en:"The vendor asks to export 50000 real citizen records from the provincial database to “train the chatbot” for next week's demo to provincial leaders; your manager agreed verbally and said to skip the paperwork."},options:{safe:{vi:"Không xuất dữ liệu thật khi chưa có căn cứ pháp lý, hợp đồng xử lý dữ liệu và đánh giá tác động; báo lãnh đạo sở bằng văn bản, dùng dữ liệu tổng hợp hoặc đã ẩn danh cho buổi trình diễn.",en:"Do not export real data without a legal basis, a processing agreement and an impact assessment; inform department leadership in writing and use synthetic or anonymized data for the demo."},shortcut:{vi:"Xuất 50000 bản ghi cho nhà thầu vì trưởng phòng đã đồng ý, xóa sau buổi trình diễn.",en:"Export the 50000 records since the manager agreed and delete them after the demo."},wait:{vi:"Không trả lời nhà thầu, để trưởng phòng tự quyết định.",en:"Do not answer the vendor and let the manager decide."}},questions:{vi:["Vì sao DVC-0315 chỉ đạt PARTIAL-ONLINE? Lợi ích 2808 triệu đồng được tính từ những dữ liệu nào?","Bạn xử lý đề nghị xuất dữ liệu công dân thật thế nào để vẫn giữ tiến độ trình diễn mà tuân thủ pháp luật?"],en:["Why does DVC-0315 only reach PARTIAL-ONLINE? Which data produces the corrected annual benefit?","How do you handle the request for real citizen data while keeping the demo on schedule and staying lawful?"]},hints:{vi:["Rà soát từng bước của quy trình: bước nào người dân vẫn phải có mặt tại quầy?","Áp dụng tỷ lệ trực tuyến và chênh lệch chi phí của đúng mức độ dịch vụ ở SOP mục 3.2.","Đọc lại SOP mục 4.2: dữ liệu cá nhân chỉ được xử lý khi có căn cứ; chỉ đạo miệng không thay thế thủ tục."],en:["Walk through each step: at which step must the citizen still appear at the counter?","Apply the online share and the cost gap of the correct service level in SOP 3.2.","Re-read SOP 4.2: personal data needs a lawful basis; a verbal instruction never replaces due process."]}},learning:{summary:{vi:"Chuyên viên chính phủ số thiết kế, triển khai và đo lường dịch vụ công trực tuyến, kết nối chia sẻ dữ liệu giữa các cơ quan và thúc đẩy chuyển đổi số khu vực công. Nghề kết hợp tư duy chiến lược, thiết kế dịch vụ lấy người dùng làm trung tâm, kiến trúc dữ liệu, an toàn thông tin và bảo vệ dữ liệu cá nhân.",en:"A GovTech and digital government specialist designs, deploys and measures online public services, connects data sharing across agencies and drives public sector digital transformation. The role combines strategic thinking, user-centered service design, data architecture, information security and personal data protection."},responsibilities:{vi:["Rà soát, đơn giản hóa và tái thiết kế quy trình thủ tục hành chính trước khi số hóa.","Đánh giá mức độ dịch vụ công trực tuyến, đề xuất lộ trình nâng lên toàn trình.","Lập đề án, phân tích chi phí - lợi ích và chỉ số đo lường cho dự án chuyển đổi số.","Điều phối kết nối dữ liệu giữa các hệ thống, bảo đảm an toàn thông tin theo cấp độ.","Giám sát nhà thầu, kiểm soát việc xử lý dữ liệu cá nhân và báo cáo kết quả triển khai."],en:["Review, simplify and redesign administrative procedures before digitizing them.","Assess online service levels and propose a roadmap to full online delivery.","Write proposals, cost-benefit analyses and metrics for digital transformation projects.","Coordinate data integration between systems with security by information system level.","Supervise vendors, control personal data processing and report deployment results."]},competencies:[{name:{vi:"Tư duy chiến lược số",en:"Digital strategy"},desc:{vi:"Xác định ưu tiên, lộ trình và chỉ số thành công gắn với nhu cầu người dân.",en:"Set priorities, roadmaps and success metrics tied to citizens' needs."}},{name:{vi:"Thiết kế dịch vụ",en:"Service design"},desc:{vi:"Vẽ hành trình người dùng, loại bỏ bước thừa và thử nghiệm nguyên mẫu.",en:"Map user journeys, remove needless steps and test prototypes."}},{name:{vi:"Kiến trúc & dữ liệu",en:"Architecture & data"},desc:{vi:"Hiểu khung kiến trúc, nền tảng tích hợp, chia sẻ dữ liệu và nguyên tắc chỉ khai báo một lần.",en:"Understand architecture frameworks, integration platforms, data sharing and the once-only principle."}},{name:{vi:"Phân tích kinh tế",en:"Economic analysis"},desc:{vi:"Tính chi phí tuân thủ, lợi ích xã hội và thời gian hoàn vốn của dự án số.",en:"Estimate compliance cost, social benefit and payback of digital projects."}},{name:{vi:"Bảo vệ dữ liệu",en:"Data protection"},desc:{vi:"Áp dụng căn cứ xử lý, ẩn danh, đánh giá tác động và kiểm soát nhà thầu.",en:"Apply lawful bases, anonymization, impact assessments and vendor controls."}}],knowledge:{vi:["Nghị định 42/2022/NĐ-CP về cung cấp thông tin và dịch vụ công trực tuyến: dịch vụ toàn trình và một phần.","Nghị định 45/2020/NĐ-CP về thực hiện thủ tục hành chính trên môi trường điện tử.","Nghị định 47/2020/NĐ-CP về quản lý, kết nối và chia sẻ dữ liệu số của cơ quan nhà nước; Luật Dữ liệu năm 2024.","Nghị định 85/2016/NĐ-CP và TCVN 11930:2017 về bảo đảm an toàn hệ thống thông tin theo cấp độ.","Luật Bảo vệ dữ liệu cá nhân năm 2025 và văn bản hướng dẫn: căn cứ xử lý, đánh giá tác động, bên xử lý dữ liệu."],en:["Decree 42/2022/ND-CP on online information and public services: full online and partial online services.","Decree 45/2020/ND-CP on administrative procedures in the electronic environment.","Decree 47/2020/ND-CP on managing, connecting and sharing digital data of state agencies; the 2024 Data Law.","Decree 85/2016/ND-CP and TCVN 11930:2017 on information system security by level.","The 2025 Personal Data Protection Law and its guidance: lawful bases, impact assessments, data processors."]},tools:["Cổng dịch vụ công và hệ thống một cửa điện tử","Nền tảng tích hợp, chia sẻ dữ liệu (LGSP)","Công cụ thiết kế trải nghiệm và nguyên mẫu","Bảng điều khiển phân tích (BI)","Công cụ quản lý dự án Agile","Công cụ ẩn danh và sinh dữ liệu tổng hợp"],kpis:{vi:["Tỷ lệ hồ sơ nộp trực tuyến trên tổng số hồ sơ.","Tỷ lệ dịch vụ công đạt mức toàn trình.","Mức độ hài lòng của người dùng (CSAT) với dịch vụ số.","Số loại giấy tờ được thay bằng dữ liệu chia sẻ, không yêu cầu nộp lại."],en:["Online filings as a share of all files.","Share of public services delivered fully online.","User satisfaction (CSAT) with digital services.","Document types replaced by shared data and no longer requested."]},day:[{time:"08:00",vi:"Xem bảng điều khiển: hồ sơ trực tuyến, lỗi kết nối, phản ánh của người dùng.",en:"Check the dashboard: online filings, integration errors and user feedback."},{time:"09:30",vi:"Làm việc với sở chuyên ngành tái thiết kế quy trình một thủ tục.",en:"Work with a line department to redesign one procedure."},{time:"13:30",vi:"Phân tích chi phí - lợi ích và cập nhật đề án nâng cấp dịch vụ.",en:"Run the cost-benefit analysis and update the service upgrade proposal."},{time:"15:00",vi:"Họp nhà thầu, rà soát kế hoạch kiểm thử và phương án dữ liệu thử nghiệm.",en:"Meet the vendor to review the test plan and test data approach."},{time:"17:00",vi:"Báo cáo tiến độ, rủi ro và kiến nghị cho lãnh đạo sở.",en:"Report progress, risks and recommendations to department leadership."}],mistakes:{vi:["Báo cáo dịch vụ là toàn trình dù vẫn còn bước bắt buộc đến trực tiếp.","Tính lợi ích trên toàn bộ hồ sơ thay vì phần thực sự chuyển sang trực tuyến.","Cho nhà thầu dùng dữ liệu công dân thật để kiểm thử mà không có căn cứ và kiểm soát."],en:["Reporting a service as fully online while an in-person step remains.","Computing benefits on all files instead of those that actually move online.","Letting vendors test with real citizen data without a legal basis and controls."]},career:[{vi:"Chuyên viên ứng dụng công nghệ thông tin",en:"IT applications officer"},{vi:"Chuyên viên chính phủ số",en:"Digital government specialist"},{vi:"Trưởng nhóm thiết kế dịch vụ và dữ liệu",en:"Service design and data lead"},{vi:"Giám đốc chuyển đổi số khu vực công",en:"Public sector chief digital officer"}],glossary:[{term:"DVC toàn trình",vi:"Dịch vụ công mà toàn bộ việc thực hiện và giải quyết thủ tục đều diễn ra trên môi trường mạng.",en:"A public service where the whole procedure is carried out and resolved online."},{term:"DVC một phần",vi:"Dịch vụ công trực tuyến chưa đáp ứng toàn trình, còn bước người dân phải thực hiện trực tiếp.",en:"An online service that is not fully online and still needs some in-person steps."},{term:"LGSP",vi:"Nền tảng tích hợp, chia sẻ dữ liệu cấp bộ, cấp tỉnh kết nối các hệ thống thông tin.",en:"Ministry or provincial data integration and sharing platform connecting information systems."},{term:"Once-only",vi:"Nguyên tắc người dân chỉ cung cấp một thông tin một lần, cơ quan nhà nước tự chia sẻ cho nhau.",en:"The principle that citizens provide information once and agencies share it among themselves."},{term:"Ẩn danh hóa",vi:"Xử lý dữ liệu để không còn xác định được cá nhân, kể cả khi kết hợp dữ liệu khác.",en:"Processing data so individuals can no longer be identified, even when combined with other data."}],quiz:[{q:{vi:"Dịch vụ cho nộp và thanh toán trực tuyến nhưng bắt buộc đến quầy ký nhận kết quả thuộc mức nào?",en:"A service allows online filing and payment but requires signing for the result at the counter. Which level is it?"},options:{vi:["Toàn trình","Không phải dịch vụ công","Một phần","Toàn trình có điều kiện"],en:["Full online","Not a public service","Partial online","Conditionally full online"]},answer:2,explain:{vi:"Còn bước bắt buộc thực hiện trực tiếp nên dịch vụ chỉ đạt mức một phần.",en:"A mandatory in-person step means the service is only partial online."}},{q:{vi:"10000 hồ sơ/năm, 50% chuyển trực tuyến, chi phí trực tiếp 150000 đ, trực tuyến 70000 đ. Lợi ích hằng năm?",en:"10000 files/year, 50% move online, in-person cost 150000 VND, online 70000 VND. What is the annual benefit?"},options:{vi:["400 triệu đồng","800 triệu đồng","750 triệu đồng","350 triệu đồng"],en:["400 million VND","800 million VND","750 million VND","350 million VND"]},answer:0,explain:{vi:"10000 x 0.5 x (150000 - 70000) = 400 triệu đồng.",en:"10000 x 0.5 x (150000 - 70000) = 400 million VND."}},{q:{vi:"Nguyên tắc “chỉ khai báo một lần” (once-only) nghĩa là gì?",en:"What does the once-only principle mean?"},options:{vi:["Mỗi người chỉ được nộp một hồ sơ","Cơ quan nhà nước tái sử dụng dữ liệu đã có thay vì yêu cầu nộp lại","Mỗi thủ tục chỉ có một bước","Chỉ được đăng nhập một lần mỗi ngày"],en:["Each person may file only once","Agencies reuse existing data instead of asking again","Each procedure has only one step","Users may log in once a day"]},answer:1,explain:{vi:"Dữ liệu người dân đã cung cấp được chia sẻ giữa các cơ quan, giảm giấy tờ phải nộp lại.",en:"Data citizens already provided is shared among agencies, cutting repeat paperwork."}},{q:{vi:"Nhà thầu xin dữ liệu công dân thật để huấn luyện chatbot cho kịp trình diễn. Bạn làm gì?",en:"A vendor wants real citizen data to train a chatbot for a demo. What do you do?"},options:{vi:["Cấp vì có chỉ đạo miệng","Cấp một nửa số bản ghi","Cấp rồi yêu cầu xóa sau","Từ chối, báo cáo bằng văn bản và dùng dữ liệu tổng hợp hoặc ẩn danh"],en:["Provide it because of a verbal order","Provide half the records","Provide it and ask for deletion later","Refuse, report in writing and use synthetic or anonymized data"]},answer:3,explain:{vi:"Xử lý dữ liệu cá nhân cần căn cứ pháp lý và kiểm soát; dữ liệu tổng hợp đáp ứng được mục tiêu trình diễn.",en:"Personal data processing needs a lawful basis and controls; synthetic data meets the demo goal."}}],tools_en:["Public service portal and one-stop-shop system","Data integration and sharing platform (LGSP)","UX design and prototyping tools","Analytics dashboard (BI)","Agile project management tools","Anonymization and synthetic data tools"]}}})})(window.KKR);
